75	
76	    /**
77	     * Syntactic email check: a non-empty local part, a single {@code @}, and a domain that contains
78	     * at least one dot. Whitespace and additional {@code @} characters are disallowed.
79	     */
80	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
81	
82	    /**
83	     * Disposable email domains that are not accepted for an owner. An email whose domain (the part
84	     * after the {@code @}, compared case-insensitively) is listed here is rejected with a 400.
85	     */
86	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
87	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
88	
89	    /**
90	     * Dedicated audit logger. Successful owner creation emits a single line here carrying the new
91	     * owner's id, customer code, registration date and membership level, so audit side-effects can
92	     * be observed independently of the HTTP response.
93	     */
94	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
95	
96	    /**
97	     * Dedicated notification logger. On successful owner creation a single welcome-notification line is
98	     * enqueued here carrying the new owner's id and member id, so the welcome side-effect can be observed
99	     * independently of the HTTP response and the audit stream.
100	     */
101	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
102	
103	    /**
104	     * Monotonically increasing sequence number stamped on each {@code OWNER_CREATED} audit event, so
105	     * the immutable event stream has a strict total order across creates. Shared across all instances
106	     * and requests; incremented once per successful owner creation.
107	     */
108	    private static final java.util.concurrent.atomic.AtomicLong OWNER_EVENT_SEQ =
109	        new java.util.concurrent.atomic.AtomicLong(0);
110	
111	    /**
112	     * Common street-type abbreviations expanded during address normalization. Keys and values are
113	     * upper-cased, matching the state of the address after whitespace and case normalization.
114	     */
115	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
116	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
117	
118	    /**
119	     * Required national-number length per E.164 country calling code. After normalization the leading
120	     * country code is stripped and the remaining national digits must match the expected count exactly
121	     * (e.g. {@code +61} requires 9 national digits, {@code +1} requires 10). Country codes not listed
122	     * here are only subject to the generic E.164 length bounds.
123	     */
124	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
125	        Map.of("1", 10, "61", 9);
126	
127	    /**
128	     * Fixed city-to-region table used to validate an owner's postcode. Cities not listed have no
129	     * known region and accept any well-formed (4-digit) postcode.
130	     */
131	    private static final Map<String, String> CITY_REGION =
132	        Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
133	
134	    /**
135	     * Inclusive 4-digit postcode range {@code [low, high]} allowed for each region: NSW 2000-2099,
136	     * VIC 3000-3099, QLD 4000-4099. A supplied postcode outside its city's region range is rejected.
137	     */
138	    private static final Map<String, int[]> REGION_POSTCODES =
139	        Map.of("NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
140	
141	    /**
142	     * Request header carrying the caller-supplied idempotency key for owner creation. When a create
143	     * repeats with a key already seen, the originally created owner is returned instead of a duplicate.
144	     */
145	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
146	
147	    /**
148	     * Maps a previously seen idempotency key to the id of the owner created under it. Populated on each
149	     * successful create that carried an {@code Idempotency-Key}, and consulted on subsequent creates so a
150	     * repeat with the same key returns the original owner rather than creating a duplicate.
151	     */
152	    private final Map<String, Integer> idempotentOwnerIds = new ConcurrentHashMap<>();
