178	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
179	        Collection<Owner> owners;
180	        if (lastName != null) {
181	            owners = this.clinicService.findOwnerByLastName(lastName);
182	        } else {
183	            owners = this.clinicService.findAllOwners();
184	        }
185	        if (owners.isEmpty()) {
