362	    /**
363	     * Counts how many existing owners share the given first and last name, compared
364	     * case-insensitively, at the moment before the new owner is persisted. The result is
365	     * stored on the owner as its {@code namesakeCount}, so it reflects the population as it
366	     * stood when the owner was created rather than being recomputed on later reads.
367	     *
368	     * @param firstName the first name of the owner being created
369	     * @param lastName the last name of the owner being created
370	     * @return the number of pre-existing owners with the same first and last name
371	     */
372	    private int countNamesakes(String firstName, String lastName) {
373	        String first = firstName == null ? "" : firstName;
374	        String last = lastName == null ? "" : lastName;
375	        return (int) this.clinicService.findAllOwners().stream()
376	            .filter(existing -> first.equalsIgnoreCase(existing.getFirstName())
377	                && last.equalsIgnoreCase(existing.getLastName()))
378	            .count();
379	    }
380	
381	    /**
382	     * Emits the immutable, structured {@code OWNER_CREATED} audit event for a freshly persisted owner.
383	     * The event is a JSON object {@code {seq, ownerId, memberId, membershipLevel, event}} published
384	     * to the {@code AUDIT} logger alongside the human-readable audit line. {@code seq} is a strictly
385	     * increasing sequence across all creates (see {@link #OWNER_EVENT_SEQ}), giving the event stream a
386	     * total order.
387	     *
388	     * <p>The identifier field carries the owner's <em>current primary identifier</em>, obtained from
389	     * {@link #primaryIdentifier(Owner)}: the unified member id, which the event carries to identify the
390	     * owner.
391	     *
392	     * @param owner the owner that was just created and persisted
393	     */
394	    /**
395	     * Enqueues a welcome notification for a freshly created owner by emitting a single line to the
396	     * dedicated {@code NOTIFY} logger carrying the new owner's id and member id. The notification is a
397	     * side-effect of a successful create only, observable independently of the HTTP response.
398	     *
399	     * @param owner the owner that was just created and persisted
400	     */
401	    private void enqueueWelcomeNotification(Owner owner) {
402	        NOTIFY.info("Welcome notification: ownerId={} memberId={}", owner.getId(), owner.getMemberId());
403	    }
404	
405	    private void emitOwnerCreatedEvent(Owner owner) {
406	        OwnerCreatedEvent event = new OwnerCreatedEvent(
407	            OWNER_EVENT_SEQ.incrementAndGet(),
408	            owner.getId(),
409	            primaryIdentifier(owner),
410	            ownerMapper.membershipLevel(owner),
411	            ownerMapper.ownerSegment(owner).getValue());
412	        AUDIT.info(event.toJson());
413	    }
414	
415	    /**
416	     * The schema version of the {@code OWNER_CREATED} audit event. Version 2 accompanies the version-2
417	     * owner identity: the event carries an explicit {@code schemaVersion} and the owner segment recomputed
418	     * from the version-2 identity.
419	     */
420	    private static final int OWNER_EVENT_SCHEMA_VERSION = 2;
421	
422	    /**
423	     * Returns the owner's current primary identifier, the single value the {@code OWNER_CREATED} audit
424	     * event carries to identify the owner: the owner's unified {@link Owner#getMemberId() member id}. It
425	     * is intentionally the only place that decides which field is "primary", so the audit event references
426	     * the member id.
427	     *
428	     * @param owner the owner being created
429	     * @return the owner's current primary identifier
430	     */
431	    private String primaryIdentifier(Owner owner) {
432	        return owner.getMemberId();
433	    }
434	
435	    /**
436	     * Immutable, structured {@code OWNER_CREATED} audit event, at schema version 2. Serialized to a compact
437	     * JSON object {@code {schemaVersion, seq, ownerId, memberId, membershipLevel, ownerSegment,
438	     * event:'OWNER_CREATED'}} for the {@code AUDIT} log. Version 2 adds the explicit {@code schemaVersion}
439	     * and the {@code ownerSegment} recomputed from the version-2 identity, and the {@code memberId} carried
440	     * is the version-2 member id. Being a record, once constructed its fields cannot change, so the emitted
441	     * event is a faithful snapshot of the owner at creation time.
442	     *
443	     * @param seq strictly increasing sequence number across all creates
444	     * @param ownerId the created owner's id
445	     * @param memberId the owner's version-2 primary identifier at creation time
446	     * @param membershipLevel the owner's effective membership level at creation time
447	     * @param ownerSegment the owner's segment recomputed from the version-2 identity at creation time
448	     */
449	    private record OwnerCreatedEvent(long seq, Integer ownerId, String memberId, Integer membershipLevel,
450	                                     String ownerSegment) {
451	
452	        private String toJson() {
453	            return "{\"schemaVersion\":" + OWNER_EVENT_SCHEMA_VERSION
454	                + ",\"seq\":" + seq
455	                + ",\"ownerId\":" + ownerId
456	                + ",\"memberId\":" + jsonValue(memberId)
457	                + ",\"membershipLevel\":" + membershipLevel
458	                + ",\"ownerSegment\":" + jsonValue(ownerSegment)
459	                + ",\"event\":\"OWNER_CREATED\"}";
460	        }
461	
462	        /** Renders a nullable string as a JSON string literal (with escaping) or {@code null}. */
463	        private static String jsonValue(String value) {
464	            if (value == null) {
465	                return "null";
466	            }
467	            StringBuilder sb = new StringBuilder(value.length() + 2);
468	            sb.append('"');
469	            for (int i = 0; i < value.length(); i++) {
470	                char c = value.charAt(i);
471	                switch (c) {
472	                    case '"' -> sb.append("\\\"");
473	                    case '\\' -> sb.append("\\\\");
474	                    case '\n' -> sb.append("\\n");
475	                    case '\r' -> sb.append("\\r");
476	                    case '\t' -> sb.append("\\t");
477	                    default -> sb.append(c);
478	                }
479	            }
480	            sb.append('"');
481	            return sb.toString();
482	        }
483	    }
484	
485	    /**
486	     * Builds the unified member id for a newly created owner, formatted {@code '<REGION><FY><HASH8><CHK>'}
487	     * where {@code REGION} is the plain region code derived from the owner's postcode (see
488	     * {@link #deriveRegion}), {@code FY} is the two-digit fiscal year of the owner's business-day-adjusted
489	     * registration date, {@code HASH8} is the first 8 upper-case hex characters of the SHA-256 digest of
490	     * {@code '<regionCodeV2>|<normalizedTelephone><lastName>'} — the {@link #regionCodeV2(String) version-2
491	     * region code} (which mixes in the fixed {@code 'V2'} tag) followed by the owner's normalized telephone
492	     * and last name — and {@code CHK} is a single Luhn check digit computed over the digits of
493	     * {@code '<REGION><FY><HASH8>'}. Mixing the {@code 'V2'} tag into the hash makes every member id differ
494	     * from the value version 1 produced, while the leading {@code REGION} segment stays the plain region so
495	     * {@code locality}, {@code timezone} and the owner segment never see the tag.
496	     *
497	     * <p>When the computed member id collides with an existing owner's member id, it is de-duplicated by
498	     * appending {@code '-<n>'} with the smallest {@code n} of 2 or more that makes the result unique across
499	     * all existing owners' member ids. The de-duplicated id is what gets assigned.
500	     *
501	     * @param owner the owner being created, whose postcode, city, registration date and last name feed the id
502	     * @param normalizedTelephone the owner's E.164-normalized telephone
503	     * @return the assigned member id, de-duplicated against existing owners if necessary
504	     */
505	    private String buildMemberId(Owner owner, String normalizedTelephone) {
506	        String region = deriveRegion(owner.getPostcode(), owner.getCity());
507	        String fiscalYear = String.format("%02d", ownerMapper.fiscalYearValue(owner.getRegistrationDate()) % 100);
508	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
509	        String hash8 = sha256Hex8(regionCodeV2(region) + "|" + normalizedTelephone + lastName);
510	        String base = region + fiscalYear + hash8;
511	        String memberId = base + luhnCheckDigit(base);
512	        Set<String> existingIds = this.clinicService.findAllOwners().stream()
513	            .map(Owner::getMemberId)
514	            .filter(id -> id != null)
515	            .collect(java.util.stream.Collectors.toSet());
516	        if (!existingIds.contains(memberId)) {
517	            return memberId;
518	        }
519	        int n = 2;
520	        while (existingIds.contains(memberId + "-" + n)) {
521	            n++;
522	        }
523	        return memberId + "-" + n;
524	    }
