526	    /**
527	     * Computes a single Luhn check digit (0-9) over the decimal digits contained in the given string.
528	     * Non-digit characters are ignored, so the check digit covers the region, fiscal-year and HASH8
529	     * digits of a member id's {@code '<REGION><FY><HASH8>'} base.
530	     *
531	     * @param value the string whose digits the check digit is computed over
532	     * @return the Luhn check digit, a single digit in {@code 0-9}
533	     */
534	    private int luhnCheckDigit(String value) {
535	        int sum = 0;
536	        boolean dbl = true;
537	        for (int i = value.length() - 1; i >= 0; i--) {
538	            char c = value.charAt(i);
539	            if (c < '0' || c > '9') {
540	                continue;
541	            }
542	            int d = c - '0';
543	            if (dbl) {
544	                d *= 2;
545	                if (d > 9) {
546	                    d -= 9;
547	                }
548	            }
549	            sum += d;
550	            dbl = !dbl;
551	        }
552	        return (10 - (sum % 10)) % 10;
553	    }
