585	    private String deriveRegion(String postcode, String city) {
586	        if (postcode != null) {
587	            try {
588	                int value = Integer.parseInt(postcode.trim());
589	                for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
590	                    int[] range = entry.getValue();
591	                    if (value >= range[0] && value <= range[1]) {
592	                        return entry.getKey();
593	                    }
594	                }
595	            } catch (NumberFormatException ex) {
596	                // Not a numeric postcode; fall back to the city table below.
597	            }
598	        }
599	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
600	    }
