602	    /**
603	     * Computes the first 8 upper-case hex characters (the first 4 bytes) of the SHA-256 digest of the
604	     * given input's UTF-8 bytes.
605	     *
606	     * @param input the string to hash
607	     * @return the 8-character upper-case hex prefix of the SHA-256 digest
608	     */
609	    private String sha256Hex8(String input) {
610	        try {
611	            byte[] digest = MessageDigest.getInstance("SHA-256")
612	                .digest(input.getBytes(StandardCharsets.UTF_8));
613	            StringBuilder hex = new StringBuilder();
614	            for (int i = 0; i < 4; i++) {
615	                hex.append(String.format("%02X", digest[i]));
616	            }
617	            return hex.toString();
618	        } catch (NoSuchAlgorithmException ex) {
619	            throw new IllegalStateException("SHA-256 not available", ex);
620	        }
621	    }
