673	    /**
674	     * Validates a supplied owner postcode. The postcode is optional: a {@code null} value is
675	     * accepted and the request stays backward-compatible. When present it must be a 4-digit value,
676	     * and must fall within the inclusive range allowed for the owner's city region per the fixed
677	     * {@link #CITY_REGION} / {@link #REGION_POSTCODES} tables (NSW 2000-2099, VIC 3000-3099,
678	     * QLD 4000-4099). A city with no known region accepts any 4-digit postcode. The value is stored
679	     * and returned exactly as given.
680	     *
681	     * @param postcode the submitted postcode, may be {@code null} when absent
682	     * @param city the owner's city, used to resolve the region whose range the postcode must satisfy
683	     * @throws InvalidOwnerFieldsException if a present postcode is not 4 digits or is out of range
684	     */
685	    private void validatePostcode(String postcode, String city) {
686	        if (postcode == null) {
687	            return;
688	        }
689	        if (!postcode.matches("[0-9]{4}")) {
690	            throw new InvalidOwnerFieldsException(List.of("postcode"));
691	        }
692	        String region = city == null ? null : CITY_REGION.get(city);
693	        if (region == null) {
694	            return;
695	        }
696	        int[] range = REGION_POSTCODES.get(region);
697	        int value = Integer.parseInt(postcode);
