703	    /**
704	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets are stripped.
705	     * A leading {@code '+'} and its country code are kept as-is; otherwise the country code {@code '+61'}
706	     * is assumed and a single leading {@code '0'} is dropped from the national digits. The result must be
707	     * a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} normalizes to
708	     * {@code "+61412345678"}. The E.164 string is what gets stored and returned.
709	     *
710	     * @param telephone the raw telephone value from the submitted owner payload
711	     * @return the normalized E.164 telephone number
712	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
713	     */
714	    private String normalizeTelephone(String telephone) {
715	        String raw = telephone == null ? "" : telephone.strip();
716	        boolean hasCountryCode = raw.startsWith("+");
717	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
718	        String digits;
719	        if (hasCountryCode) {
720	            digits = cleaned.substring(1);
721	        } else {
722	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
723	            digits = "61" + national;
724	        }
725	        if (!digits.matches("[0-9]{8,15}")) {
726	            throw new InvalidOwnerFieldsException(List.of("telephone"));
727	        }
728	        validateNationalNumberLength(digits);
729	        return "+" + digits;
730	    }
731	
732	    /**
733	     * Validates that the national-number portion of a normalized E.164 number (the digits after the
734	     * country calling code) has the exact length required for that country. The country code is matched
735	     * against {@link #NATIONAL_NUMBER_LENGTHS} (e.g. {@code +61} requires 9 national digits, {@code +1}
736	     * requires 10). Numbers whose country code is not listed are left to the generic length bounds.
737	     *
738	     * @param digits the normalized E.164 digits, without the leading {@code '+'}
739	     * @throws InvalidOwnerFieldsException if the national-number length is wrong for the country code
740	     */
741	    private void validateNationalNumberLength(String digits) {
742	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTHS.entrySet()) {
743	            String countryCode = entry.getKey();
744	            if (digits.startsWith(countryCode)) {
745	                int nationalLength = digits.length() - countryCode.length();
746	                if (nationalLength != entry.getValue()) {
747	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
748	                }
749	                return;
750	            }
751	        }
752	    }
