754	    /**
755	     * Normalizes an optional owner email. A {@code null} value is left untouched (the field is optional).
756	     * When a value is present it must be a syntactically valid address (see {@link #EMAIL_PATTERN}); the
757	     * accepted value is trimmed and lower-cased before it is stored and returned.
758	     *
759	     * @param email the raw email value from the submitted owner payload, may be {@code null}
760	     * @return {@code null} if no email was supplied, otherwise the lower-cased email
761	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address,
762	     *         or if its domain is on the disposable-domain blocklist ({@link #DISPOSABLE_EMAIL_DOMAINS})
763	     */
764	    private String normalizeEmail(String email) {
765	        if (email == null) {
766	            return null;
767	        }
768	        String trimmed = email.strip();
769	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
770	            throw new InvalidOwnerFieldsException(List.of("email"));
771	        }
772	        String normalized = trimmed.toLowerCase(Locale.ROOT);
773	        String domain = normalized.substring(normalized.indexOf('@') + 1);
774	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
775	            throw new InvalidOwnerFieldsException(List.of("email"));
776	        }
777	        return normalized;
778	    }
