780	    /**
781	     * Rejects creating an owner whose derived identity key (the SHA-256 hex digest of
782	     * {@code '<normalizedTelephone>|<lowerEmail>|<soundex(lastName)>'}, see {@link OwnerMapper#identityKey})
783	     * exactly equals that of an existing non-deleted owner. Two owners are treated as duplicates only when
784	     * their whole identity keys match, so owners who share a last-name Soundex but differ in telephone or
785	     * email are not duplicates and are admitted (flagged as a soft match instead). Such an owner is rejected
786	     * with a 409, <em>unless</em> the request opts into {@code sharesHousehold}, which bypasses the block
787	     * entirely.
788	     *
789	     * @param owner the owner being created, whose identity key is matched
790	     * @param sharesHousehold whether the request declared the owner a shared-household member
791	     * @throws DuplicateOwnerIdentityException if another owner already has the same identity key
792	     */
793	    private void rejectDuplicateIdentity(Owner owner, boolean sharesHousehold) {
794	        if (sharesHousehold) {
795	            return;
796	        }
797	        String identityKey = ownerMapper.identityKey(owner);
798	        boolean duplicate = this.clinicService.findAllOwners().stream()
799	            .filter(existing -> !isDeleted(existing))
800	            .anyMatch(existing -> identityKey.equals(ownerMapper.identityKey(existing)));
