806	    /**
807	     * Flags a soft ("possible") duplicate on the owner being created. Unlike a hard duplicate (which is
808	     * rejected outright by {@link #rejectDuplicateIdentity}), a soft duplicate is still created: it is an
809	     * owner whose {@link OwnerMapper#identityKey identity key} <em>differs</em> from an existing owner's
810	     * but which shares that owner's last-name {@link OwnerMapper#soundex Soundex code} and postcode. When
811	     * such an existing owner is found, {@code possibleDuplicate} is set {@code true} and
812	     * {@code possibleDuplicateOf} is set to that owner's id (the earliest by id when several match); otherwise
813	     * {@code possibleDuplicate} is {@code false} and {@code possibleDuplicateOf} stays {@code null}. Both values
814	     * are snapshotted on the owner so they reflect the population as it stood when the owner was created.
815	     *
816	     * <p>Because the telephone is part of the identity key, two owners with the same last name and postcode
817	     * but different telephones no longer collide on the identity key, so they are admitted as a soft match
818	     * here rather than rejected as a hard household duplicate.
819	     *
820	     * <p>A declared household member (a request that set {@code sharesHousehold} to bypass the duplicate
821	     * block) is never a <em>suspected</em> duplicate: it is knowingly created as another member of the
822	     * household, so {@code possibleDuplicate} is left {@code false} and {@code possibleDuplicateOf}
823	     * {@code null} without consulting the existing population.
824	     *
825	     * @param owner the owner being created, whose last-name Soundex and postcode are matched
826	     * @param sharesHousehold whether the request declared the owner a shared-household member
827	     */
828	    private void assignPossibleDuplicate(Owner owner, boolean sharesHousehold) {
829	        if (sharesHousehold) {
830	            owner.setPossibleDuplicateOf(null);
831	            owner.setPossibleDuplicate(false);
832	            return;
833	        }
834	        String postcode = owner.getPostcode();
835	        Integer matchId = null;
836	        if (postcode != null) {
837	            String identityKey = ownerMapper.identityKey(owner);
838	            String lastNameCode = OwnerIdentity.soundex(owner.getLastName());
839	            for (Owner existing : this.clinicService.findAllOwners()) {
840	                if (!isDeleted(existing)
841	                    && postcode.equals(existing.getPostcode())
842	                    && lastNameCode.equals(OwnerIdentity.soundex(existing.getLastName()))
843	                    && !identityKey.equals(ownerMapper.identityKey(existing))
844	                    && existing.getId() != null
845	                    && (matchId == null || existing.getId() < matchId)) {
846	                    matchId = existing.getId();
847	                }
848	            }
849	        }
850	        owner.setPossibleDuplicateOf(matchId);
851	        owner.setPossibleDuplicate(matchId != null);
852	    }
