1026	    /**
1027	     * Computes the membership-level ceiling for the owner being created, snapshotted at creation time.
1028	     * A new owner's membership level cannot exceed one above the current maximum membership level among
1029	     * their existing household members: the returned cap is that maximum plus one. Existing household
1030	     * members are the non-deleted owners already carrying the same {@code householdId}, and their
1031	     * membership level is their effective (already-capped) {@link OwnerMapper#membershipLevel level}.
1032	     * Returns {@code null} when there is no existing household member, in which case no cap applies.
1033	     *
1034	     * @param householdId the household identifier assigned to the owner being created, may be {@code null}
1035	     * @return one above the highest household member's membership level, or {@code null} when none exist
1036	     */
1037	    private Integer membershipLevelCap(String householdId) {
1038	        if (householdId == null) {
1039	            return null;
1040	        }
1041	        java.util.OptionalInt maxLevel = this.clinicService.findAllOwners().stream()
1042	            .filter(existing -> !isDeleted(existing))
1043	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
1044	            .mapToInt(existing -> ownerMapper.membershipLevel(existing))
1045	            .max();
1046	        return maxLevel.isPresent() ? maxLevel.getAsInt() + 1 : null;
1047	    }
1048	
1049	    /**
1050	     * Derives the deterministic version-2 household identifier for an owner: the first 12 hex characters
1051	     * of the SHA-256 digest of {@code '<regionCodeV2>|<normalizedLastName>|<postcode>'}, where the leading
1052	     * segment is the {@link #regionCodeV2(String) version-2 region code} (which mixes in the fixed
1053	     * {@code 'V2'} tag), the last name is normalized for case- and whitespace-insensitive comparison (see
1054	     * {@link #normalizeForComparison}) and a {@code null} postcode contributes an empty segment. Mixing the
1055	     * {@code 'V2'} tag in makes the identifier differ from the value version 1 produced; every owner that
1056	     * shares a last name and postcode still resolves to the exact same identifier, regardless of creation
1057	     * order, making them members of one household.
1058	     *
1059	     * @param owner the owner being created, whose last name, postcode and derived region feed the id
1060	     * @return the deterministic household identifier
1061	     */
1062	    private String householdId(Owner owner) {
1063	        String region = deriveRegion(owner.getPostcode(), owner.getCity());
1064	        String lastName = owner.getLastName();
1065	        String postcode = owner.getPostcode();
1066	        String key = regionCodeV2(region) + "|" + normalizeForComparison(lastName)
1067	            + "|" + (postcode == null ? "" : postcode);
1068	        try {
1069	            byte[] digest = MessageDigest.getInstance("SHA-256")
1070	                .digest(key.getBytes(StandardCharsets.UTF_8));
1071	            StringBuilder hex = new StringBuilder();
1072	            for (int i = 0; i < 6; i++) {
1073	                hex.append(String.format("%02x", digest[i]));
1074	            }
1075	            return hex.toString();
1076	        } catch (NoSuchAlgorithmException ex) {
1077	            throw new IllegalStateException("SHA-256 not available", ex);
1078	        }
1079	    }
1080	
1081	    /**
1082	     * Normalizes a value for case-insensitive, whitespace-insensitive comparison: leading and trailing
1083	     * whitespace is stripped, every run of internal whitespace is collapsed to a single space, and the
1084	     * result is lower-cased. A {@code null} value normalizes to the empty string.
1085	     *
1086	     * @param value the value to normalize, may be {@code null}
1087	     * @return the normalized value
1088	     */
1089	    private String normalizeForComparison(String value) {
1090	        if (value == null) {
1091	            return "";
1092	        }
1093	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
1094	    }
1095	
1096	    /**
1097	     * Normalizes an owner address for storage and comparison: leading and trailing whitespace is
1098	     * stripped, every run of internal whitespace is collapsed to a single space, the value is
1099	     * upper-cased, and common street-type abbreviations are expanded ({@code ST -> STREET},
1100	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). For example {@code "  12  main  st "} normalizes to
1101	     * {@code "12 MAIN STREET"}. A {@code null} value normalizes to the empty string. This is the form
1102	     * that is stored, returned, and used for every address comparison (household duplicate detection
1103	     * and the shared household id).
1104	     *
1105	     * @param address the raw address value from the submitted owner payload, may be {@code null}
1106	     * @return the normalized address
1107	     */
1108	    /**
1109	     * Applies address normalization to the owner and derives the composed {@code address}, preferring
1110	     * the structured fields over the flat {@code address} input for backward compatibility. When a
1111	     * non-blank {@code addressLine1} is supplied, both structured lines are normalized (see
1112	     * {@link #normalizeAddress}) and stored, and the composed {@code address} becomes the normalized
1113	     * {@code addressLine1}, with a single space and the normalized {@code addressLine2} appended when an
1114	     * {@code addressLine2} was supplied. Otherwise the flat {@code address} is normalized and stored, and
1115	     * the structured lines are cleared. The stored {@code address} is the form every later step reads.
1116	     *
1117	     * @param owner the owner being created, whose raw address fields are normalized in place
1118	     */
1119	    private void applyAddress(Owner owner) {
1120	        String line1 = owner.getAddressLine1();
1121	        if (line1 != null && !line1.isBlank()) {
1122	            String normalizedLine1 = normalizeAddress(line1);
1123	            String normalizedLine2 = normalizeAddress(owner.getAddressLine2());
1124	            owner.setAddressLine1(normalizedLine1);
1125	            if (!normalizedLine2.isEmpty()) {
1126	                owner.setAddressLine2(normalizedLine2);
1127	                owner.setAddress(normalizedLine1 + " " + normalizedLine2);
1128	            } else {
1129	                owner.setAddressLine2(null);
1130	                owner.setAddress(normalizedLine1);
1131	            }
1132	        } else {
1133	            owner.setAddressLine1(null);
1134	            owner.setAddressLine2(null);
1135	            owner.setAddress(normalizeAddress(owner.getAddress()));
1136	        }
1137	    }
1138	
1139	    private String normalizeAddress(String address) {
1140	        if (address == null) {
1141	            return "";
1142	        }
1143	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
1144	        if (collapsed.isEmpty()) {
1145	            return "";
1146	        }
1147	        String[] tokens = collapsed.split(" ");
1148	        StringBuilder normalized = new StringBuilder();
1149	        for (int i = 0; i < tokens.length; i++) {
1150	            if (i > 0) {
1151	                normalized.append(' ');
1152	            }
1153	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
1154	        }
1155	        return normalized.toString();
1156	    }
1157	}
